"""Intent tests for M1-T17: rolling volatility from earlier returns (RISK-02, TC-05)."""

from __future__ import annotations

from collections.abc import Callable
from typing import Any

import pytest

import risk
from risk.types import Returns, VolSeries

Golden = Callable[[str, str], tuple[dict[str, Any], dict[str, Any]]]
Sample = Callable[[str], dict[str, Any]]


def make_returns(payload: dict[str, Any]) -> Returns:
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={t: tuple(v) for t, v in payload["values"].items()},
    )


def assert_matches_expected(vol: VolSeries, expected: dict[str, Any]) -> None:
    tol = expected["tol"]
    assert vol.window == expected["window"]
    assert vol.annualized is expected["annualized"]
    assert set(vol.values) == set(expected["values"])
    for ticker, want in expected["values"].items():
        got = vol.values[ticker]
        assert len(got) == len(want), ticker
        for i, (g, w) in enumerate(zip(got, want, strict=True)):
            if w is None:
                assert g is None, f"{ticker}[{i}] should have no value"
            else:
                assert g is not None, f"{ticker}[{i}] should have a value"
                assert g == pytest.approx(w, abs=tol), f"{ticker}[{i}]"


@pytest.mark.intent
def test_tc05_rolling_vol_known_answer(golden: Golden) -> None:
    inp, expected = golden("risk", "TC-05")
    returns = make_returns(inp["returns"])
    vol = risk.rolling_vol(returns, inp["window"])
    assert_matches_expected(vol, expected)
    assert vol.returns == returns


@pytest.mark.intent
def test_tc05_value_never_uses_its_own_date_return(golden: Golden) -> None:
    """RISK-02: the last date's return is in no window, so changing it changes nothing."""
    inp, expected = golden("risk", "TC-05")
    payload = inp["returns"]
    perturbed = {t: [*v[:-1], v[-1] + 0.5] for t, v in payload["values"].items()}
    returns = make_returns({**payload, "values": perturbed})
    vol = risk.rolling_vol(returns, inp["window"])
    assert_matches_expected(vol, expected)


@pytest.mark.intent
@pytest.mark.parametrize("window", [1, 0, -3])
def test_window_below_two_is_a_value_error(window: int, contract_sample: Sample) -> None:
    returns = make_returns(contract_sample("risk.Returns"))
    with pytest.raises(ValueError, match=r"window"):
        risk.rolling_vol(returns, window)

